package local.lito381.server;
/** Actual status transitions and expiry/wire arithmetic, no player/Hub/socket/SQL fixture. */
public final class SourceDollSlowPlan {
 static int cases;static void check(boolean b,String name){if(!b)throw new AssertionError(name);cases++;}
 static final class Pet {volatile long hasteExpiresAtNanos,slowExpiresAtNanos;int hasteSkillId,slowSkillId,moveSpeed;volatile Object nativeSourceDollSlowEpoch;}
 public static void main(String[]args){long now=1000000000L;
  var zero=new BattleTimedStatus();var z=NativeSourceDollSlow.pcChange(zero,now,0);check(z.type()==2&&z.durationSeconds()==0,"Source zero seconds applies slow");check((long)CombatAccess.field(zero,"slowExpiresAtNanos")==Long.MAX_VALUE,"zero uses permanent original scalar");check(zero.speed(now).type()==2&&zero.speed(now).remainingSeconds()==0,"actual synchronized query handles permanent without overflow");check(!zero.expireSlowLease(now+99999999999999L).expired(),"permanent is not prematurely expired");check(NativeSourceDollSlow.pcChange(zero,now+1,100)==null,"already slow does not refresh permanent");zero.cancelMagicEffects();check(zero.speed(now).type()==0,"existing cancellation clears permanent");
  var longSlow=new BattleTimedStatus();NativeSourceDollSlow.pcChange(longSlow,now,70000);check(longSlow.speed(now).remainingSeconds()==(70000&65535),"actual query preserves Source writeH for long duration");check(longSlow.speed(now+70000000000000L).type()==0&&longSlow.expireSlowLease(now+70000000000000L).expired(),"long lease expires on original path");
  check(NativeSourceDollSlow.remaining(now+65536000000000L,now)==0,"live 65536 seconds writes zero without implying expiry");check(NativeSourceDollSlow.remaining(now+1000000001L,now)==2,"partial second rounds up");check(!NativeSourceDollSlow.active(now,now),"exact expiry rejected");check(NativeSourceDollSlow.remaining(Long.MAX_VALUE,now)==0,"permanent self wire duration zero");
  var haste=new BattleTimedStatus();haste.activateHaste(now,20,43);var c=NativeSourceDollSlow.pcChange(haste,now+1,0);check(c.type()==0&&c.stoppedSkillId()==43&&haste.speed(now+2).type()==0,"zero duration still cancels recognized haste without adding slow");
  var innate=new Pet();innate.moveSpeed=1;check(NativeSourceDollSlow.change(innate,now,10,1,true,true)==null&&innate.moveSpeed==1&&innate.slowExpiresAtNanos==0,"innate pet haste has no removable skill, unchanged");innate.hasteSkillId=43;innate.hasteExpiresAtNanos=now+10000000000L;var cancelled=NativeSourceDollSlow.change(innate,now,10,1,true,true);check(cancelled.type()==0&&innate.moveSpeed==0&&innate.hasteSkillId==0&&innate.hasteExpiresAtNanos==0,"actual pet fields cancel recognized haste");
  var pet=new Pet();var p=NativeSourceDollSlow.change(pet,now,0,0,true,true);check(p.type()==2&&pet.moveSpeed==2&&pet.slowSkillId==29&&pet.slowExpiresAtNanos==Long.MAX_VALUE,"pet permanent slow uses original state fields");long expiry=pet.slowExpiresAtNanos;check(NativeSourceDollSlow.change(pet,now+1,20,2,true,true)==null&&pet.slowExpiresAtNanos==expiry,"already slow pet unchanged");
  var unknown=new Pet();unknown.moveSpeed=1;unknown.hasteSkillId=999;unknown.hasteExpiresAtNanos=now+10000000000L;check(NativeSourceDollSlow.change(unknown,now,10,1,true,true)==null&&unknown.hasteSkillId==999,"unrecognized speed source not removed");
  check(NativeSourceDollSlow.expires(now,2147484)==Long.MAX_VALUE,"Source int milliseconds overflow negative selects permanent");int wrapped=4294968*1000;check(wrapped>0&&NativeSourceDollSlow.expires(now,4294968)==now+1000000000L,"positive wrapped subsecond Source timer expires at first tick");
  try{NativeSourceDollSlow.expires(now,-1);throw new AssertionError();}catch(IllegalArgumentException expected){cases++;}
  var permanent=new BattleTimedStatus();long realNow=System.nanoTime();NativeSourceDollSlow.pcChange(permanent,realNow,0);var proof=new NativeSourceDollOutput.Speed(new Object(),permanent,0,Long.MAX_VALUE,2);check(proof.current(),"actual detached permanent proof current");Object firstEpoch=proof.nativeSourceDollSlowEpoch;permanent.cancelMagicEffects();NativeSourceDollSlow.pcChange(permanent,realNow+1,0);check(!proof.current()&&firstEpoch!=CombatAccess.field(permanent,"nativeSourceDollSlowEpoch"),"clear and reapply same permanent expiry rejects old actual proof");var next=new NativeSourceDollOutput.Speed(new Object(),permanent,0,Long.MAX_VALUE,2);check(next.current(),"new permanent proof current after ABA replacement");NativeSourceDollSlow.pcChange(permanent,realNow+2,0);check(next.current()&&next.nativeSourceDollSlowEpoch==CombatAccess.field(permanent,"nativeSourceDollSlowEpoch"),"no-op already slow preserves accepted epoch");
  if(cases!=25)throw new AssertionError(cases);System.out.println("PASS25 Source zero/long/int-millisecond/innate-haste and actual status clear/expiry scenarios; no player/Hub/socket/SQL");
 }
}
